code_examples.nodejs_setup_provider:
const { providers, Wallet } = require('ethers');
const { FlashbotsBundleProvider } = require('@flashbots/ethers-provider-bundle');

const ETHEREUM_RPC_URL = 'https://rpc.flashbots.net';
const provider = new providers.JsonRpcProvider(ETHEREUM_RPC_URL);
const authSigner = Wallet.createRandom();

const flashbotsProvider = await FlashbotsBundleProvider.create(
  provider,
  authSigner
);

code_examples.nodejs_send_bundle:
const blockNumber = await provider.getBlockNumber();
const bundleResponse = await flashbotsProvider.sendBundle(
  [
    {
      signedTransaction: SIGNED_TX_HEX
    },
    {
      signer: wallet,
      transaction: {
        to: RECIPIENT_ADDRESS,
        value: ethers.utils.parseEther('0.01'),
        gasPrice: ethers.utils.parseUnits('100', 'gwei'),
        gasLimit: 21000,
        nonce: await provider.getTransactionCount(wallet.address)
      }
    }
  ],
  blockNumber + 1
);
if ('error' in bundleResponse) {
  console.warn('sendBundle error', bundleResponse.error);
}

code_examples.nodejs_simulate_bundle:
const signedTransactions = await flashbotsProvider.signBundle(bundle);
const blockNumber = await provider.getBlockNumber();
const simulation = await flashbotsProvider.simulate(signedTransactions, blockNumber + 1);
if ('error' in simulation) {
  console.warn('Simulation error:', simulation.error);
} else {
  console.log('Simulation success:', simulation);
}

code_examples.nodejs_send_to_multiple_blocks:
const blockNumber = await provider.getBlockNumber();
const minTimestamp = (await provider.getBlock(blockNumber)).timestamp;
const maxTimestamp = minTimestamp + 120;

const bundlePromises = [blockNumber + 1, blockNumber + 2].map((targetBlock) =>
  flashbotsProvider.sendBundle(
    bundle,
    targetBlock,
    { minTimestamp, maxTimestamp }
  )
);
await Promise.all(bundlePromises);

code_examples.nodejs_eip1559_bundle:
const block = await provider.getBlock(blockNumber);
const maxBaseFee = FlashbotsBundleProvider.getMaxBaseFeeInFutureBlock(block.baseFeePerGas, 1);
const PRIORITY_FEE = ethers.BigNumber.from(1e9);

const eip1559tx = {
  to: wallet.address,
  type: 2,
  maxFeePerGas: PRIORITY_FEE.add(maxBaseFee),
  maxPriorityFeePerGas: PRIORITY_FEE,
  gasLimit: 21000,
  data: '0x',
  chainId: 1
};

code_examples.nodejs_mev_share_send_bundle:
import MevShareClient from '@flashbots/mev-share-client';

const mevShareClient = MevShareClient.useEthereumMainnet(authSigner);

const params = {
  inclusion: { block: TARGET_BLOCK, maxBlock: TARGET_BLOCK + 2 },
  body: [
    { tx: SIGNED_TX_HEX, canRevert: false }
  ],
  privacy: {
    hints: { calldata: true, logs: true, txHash: true }
  }
};

const result = await mevShareClient.sendBundle(params);
console.log('Bundle hash:', result.bundleHash);
